UPDATE build_space_document
SET name = #{document.name}, draft_json = #{document.draftJson}, revision = revision + 1,
    update_by = #{document.updateBy}, update_time = #{document.updateTime}
WHERE project_id = #{document.projectId} AND space_id = #{document.spaceId} AND revision = #{baseRevision}

UPDATE build_space_document
SET draft_json = #{snapshotJson}, published_json = #{snapshotJson},
    revision = #{baseRevision} + 1, published_revision = #{baseRevision} + 1, published_at = #{publishedAt},
    update_by = #{username}, update_time = #{publishedAt}
WHERE project_id = #{projectId} AND revision = #{baseRevision}
